func (this *TreeItem) GetTextBoundsInPixels(index int32) *Rectangle {
	if !this.parent.CheckData(this, true) {
		this.Error(ERROR_WIDGET_DISPOSED)
	}
	var rect *win32.RECT = this.GetBoundsIndexGetTextGetImageFullText(index, true, false, true)
	if index == 0 {
		rect.Left += TreeINSET - 1
	}
	rect.Left = int32(math.Min(float64(rect.Left), float64(rect.Right)))
	rect.Right = rect.Right - TreeINSET + 1
	var width int32 = int32(math.Max(float64(0), float64(rect.Right-rect.Left)))
	var height int32 = int32(math.Max(float64(0), float64(rect.Bottom-rect.Top)))
	return NewRectangle(rect.Left, rect.Top, width, height)
}

func (this *TreeItem) handleDPIChange_(event *Event, scalingFactor float32) {
	this.Item.handleDPIChange_(event, scalingFactor)
	if this.images != (nil) {
		for i := int32(1); i < int32(len(this.images)); i++ {
			this.SetImageIndexImage(i, this.images[i])
		}
	}
	if this.font != (nil) {
		this.SetFont(this.font)
	}
	var cellFonts []*Font = this.cellFont
	if cellFonts != (nil) {
		for index := int32(0); index < int32(len(cellFonts)); index++ {
			var cellFont *Font = cellFonts[index]
			if cellFont == (nil) {
				cellFonts[index] = nil
			} else {
				cellFonts[index] = FontWin32_newFontTargetZoom(cellFont, this.NativeZoom)
			}
		}
	}
	for _, item := range this.GetItems() {
		if item != (nil) && !item.IsDisposed() {
			item.NotifyListeners(ZoomChanged, event)
		}
	}
}
